if(!window.__jrtlMachineListExcelReady){window.__jrtlMachineListExcelReady=true;(function(){
const label="ดาวน์โหลด M/C List Excel";
const escapeCell=value=>String(value??"").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;");
const exportList=root=>{
 const cards=[...root.querySelectorAll(".equipment-cards > details.equipment-card")];
 const records=cards.map(card=>{
  const summary=card.querySelector("summary");
  const fields=[...card.querySelectorAll("dl > div")].map(field=>[field.querySelector("dt")?.textContent?.trim()||"",field.querySelector("dd")?.textContent?.trim()||""]);
  const spans=[...(summary?.querySelectorAll(":scope > span")||[])].map(item=>item.textContent?.trim()||"");
  return {no:summary?.querySelector("strong")?.textContent?.trim()||"",status:summary?.querySelector(".equipment-status")?.textContent?.trim()||"",name:summary?.querySelector(":scope > b")?.textContent?.trim()||"",categoryModel:spans[0]||"",details:Object.fromEntries(fields)};
 });
 const labels=[...new Set(records.flatMap(record=>Object.keys(record.details)))];
 const rows=[["หมายเลขเครื่อง / Equipment No.","ชื่อเครื่อง / Machine Name","หมวด · รุ่น / Category · Model","สถานะ / Status",...labels],...records.map(record=>[record.no,record.name,record.categoryModel,record.status,...labels.map(key=>record.details[key]||"")])];
 const table=rows.map((row,index)=>"<tr>"+row.map(cell=>"<td"+(index===0?' style="font-weight:bold;background:#dceaf6"':"")+">"+escapeCell(cell)+"</td>").join("")+"</tr>").join("");
 const html='<html><head><meta charset="utf-8"></head><body><table>'+table+"</table></body></html>";
 const url=URL.createObjectURL(new Blob(["\\ufeff",html],{type:"application/vnd.ms-excel;charset=utf-8"}));
 const link=document.createElement("a");link.href=url;link.download="JRTL-MC-List.xls";link.click();setTimeout(()=>URL.revokeObjectURL(url),1500);
};
const setLabel=()=>document.querySelectorAll(".equipment-registry .equipment-heading button").forEach(button=>{if(button.textContent!==label)button.textContent=label;button.title="ดาวน์โหลดรายการเครื่องจักรตามตัวกรองเป็นไฟล์ Excel";});
new MutationObserver(setLabel).observe(document.documentElement,{childList:true,subtree:true});
setLabel();
document.addEventListener("click",event=>{
 const target=event.target instanceof Element?event.target:event.target?.parentElement;
 const button=target?.closest?.(".equipment-registry .equipment-heading button");
 const root=button?.closest(".equipment-registry");
 if(!root)return;
 event.preventDefault();event.stopImmediatePropagation();exportList(root);
},true);
})();}
