// Calendar weeks follow the factory's Bangkok timezone, Monday through Sunday.
function currentDashboardWeek(now = new Date()) {
    const parts = new Intl.DateTimeFormat('en-CA', {
        timeZone: 'Asia/Bangkok', year: 'numeric', month: '2-digit', day: '2-digit',
    }).formatToParts(now);
    const part = (name) => parts.find(p => p.type === name).value;
    const start = new Date(`${part('year')}-${part('month')}-${part('day')}T00:00:00Z`);
    start.setUTCDate(start.getUTCDate() - (start.getUTCDay() + 6) % 7);
    const end = new Date(start);
    end.setUTCDate(end.getUTCDate() + 6);
    return { from: start.toISOString().slice(0, 10), to: end.toISOString().slice(0, 10) };
}
function advanceDashboardWeek(filters, previous, next) {
    return filters.from === previous.from && filters.to === previous.to
        ? { ...filters, ...next } : filters;
}

function useWeeklyDashboardFilters() {
  const [filters,setFilters]=(0,k.useState)(()=>({machineId:"",shift:"",...currentDashboardWeek()}));
    (0,k.useEffect)(() => {
    let previous = currentDashboardWeek();
    const refreshWeek = () => {
      const next = currentDashboardWeek();
      if (next.from !== previous.from) {
        const old = previous;
        setFilters(filters => advanceDashboardWeek(filters, old, next));
        previous = next;
      }
    };
    const timer = window.setInterval(refreshWeek, 30000);
    window.addEventListener("focus", refreshWeek);
    document.addEventListener("visibilitychange", refreshWeek);
    return () => {
      window.clearInterval(timer);
      window.removeEventListener("focus", refreshWeek);
      document.removeEventListener("visibilitychange", refreshWeek);
    };
  }, []);
  return [filters,setFilters];
}

